            byte_offset = int.from_bytes(payload[2:4], "little")
            if page_index >= num_pages or byte_offset + byte_count > page_len:
                break
        elif kind == KIND_COMMIT:
            if payload_length != 8:
                break
        elif kind == KIND_ABORT:
            if payload_length != 0:
                break
        else:
